import { trace, unique_ID, getUrlVars, ratio } from "../../core/Util"
import { Media } from "../Media";

export default class Bilibili extends Media {
    _loadMedia() {
        var self = this;

        this.bilibili_loaded = false;
        this.saved_src = "";
        this._observer = null;
        this._is_active = true;

        // Create Dom element
        this._el.content_item = this.domCreate("div", "tl-media-item tl-media-iframe tl-media-bilibili tl-media-shadow", this._el.content);
        this._el.content_item.id = unique_ID(7);

        this.media_id = this._parseMediaId(this.data.url);

        if (!this.media_id.id || !this.media_id.id_type) {
            trace("BILIBILI IN URL BUT NOT A VALID VIDEO");
            this.loadErrorDisplay("Invalid Bilibili URL");
            return;
        }

        this.player = this.domCreate("iframe", "", this._el.content_item);
        this.player.addEventListener("load", function() {
            self.onPlayerReady();
            self.onLoaded();
        });

        this.player.width = "100%";
        this.player.height = "100%";
        this.player.frameBorder = "0";
        this.player.scrolling = "no";
        this.player.src = this._buildEmbedUrl();
        this.player.setAttribute("allowfullscreen", "");
        this.player.setAttribute("webkitallowfullscreen", "");
        this.player.setAttribute("mozallowfullscreen", "");
        this.player.setAttribute("allow", "accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share");

        this._setupVisibilityPause();
    }

    _setupVisibilityPause() {
        var self = this;

        if (this._observer) {
            this._observer.disconnect();
            this._observer = null;
        }

        this._observer = new IntersectionObserver(function(entries) {
            entries.forEach(function(entry) {
                if (!self._is_active) {
                    return;
                }

                if (!entry.isIntersecting) {
                    self.pauseMedia();
                } else {
                    self.playMedia();
                }
            });
        }, { threshold: 0 });

        this._observer.observe(this._el.content_item);
    }

    _updateMediaDisplay() {
        this._el.content_item.style.height = ratio.r16_9({ w: this.options.width }) + "px";
        this._el.content_item.style.width = this.options.width + "px";

        // Only restore the iframe when the owning slide is active.
        if (this._is_active && this.player.src == "about:blank") {
            if (this.saved_src) {
                this.player.src = this.saved_src;
                this.saved_src = "";
            } else {
                this.player.src = this._buildEmbedUrl();
            }
        }
    }

    _stopMedia() {
        this._is_active = false;

        if (this._observer) {
            this._observer.disconnect();
            this._observer = null;
        }

        this.pauseMedia();
    }

    playMedia() {
        try {
            this._is_active = true;

            if (!this._observer && this._el.content_item) {
                this._setupVisibilityPause();
            }

            if (this.player && this.saved_src && this.player.src == "about:blank") {
                this.player.src = this.saved_src;
                this.saved_src = "";
            }
        } catch (err) {
            trace(err);
        }
    }

    pauseMedia() {
        try {
            if (this.player && this.player.src && this.player.src != "about:blank") {
                this.saved_src = this.player.src;
                this.player.src = "about:blank";
            }
        } catch (err) {
            trace(err);
        }
    }

    _parseMediaId(url) {
        var url_vars = getUrlVars(url),
            result = {
                id: null,
                id_type: null
            },
            bv_match = url.match(/\/video\/(BV[0-9A-Za-z]+)/i),
            av_match = url.match(/\/video\/(av\d+)/i);

        if (url_vars["bvid"]) {
            result.id = url_vars["bvid"];
            result.id_type = "bvid";
        } else if (url_vars["aid"]) {
            result.id = url_vars["aid"];
            result.id_type = "aid";
        } else if (bv_match && bv_match[1]) {
            result.id = bv_match[1];
            result.id_type = "bvid";
        } else if (av_match && av_match[1]) {
            result.id = av_match[1].replace(/^av/i, "");
            result.id_type = "aid";
        }

        return result;
    }

    _buildEmbedUrl() {
        var params = ["page=1", "high_quality=1", "danmaku=0"];

        if (this.media_id.id_type == "bvid") {
            params.push("bvid=" + encodeURIComponent(this.media_id.id));
        } else {
            params.push("aid=" + encodeURIComponent(this.media_id.id));
        }

        return "https://player.bilibili.com/player.html?" + params.join("&");
    }

    onPlayerReady() {
        this.bilibili_loaded = true;
        this._el.content_item = document.getElementById(this._el.content_item.id);
        this.onMediaLoaded();
    }
}
